class Counter:
    def __init__(self, start):
        self.value = start

    def increment(self):
        self.value += 1
        return self.value

start = int(input())
n = int(input())
c = Counter(start)
for _ in range(n):
    print(c.increment())

class Box:
    def __init__(self, length, width, height):
        self.length = length
        self.width = width
        self.height = height

    def volume(self):
        return self.length * self.width * self.height

length, width, height = map(int, input().split())
b = Box(length, width, height)
print(b.volume())

class Student:
    def __init__(self, name, marks):
        self.name = name
        self.marks = marks

    def average(self):
        total = 0
        for m in self.marks:
            total += m
        return total / len(self.marks)

name = input()
n = int(input())
marks = list(map(int, input().split()))
s = Student(name, marks)
print(f"{s.name}: {s.average():.2f}")

