class Thermostat:
    def __init__(self, current, target):
        self.current = current
        self.target = target

    def verdict(self):
        if self.current < self.target:
            return "WARMING"
        if self.current > self.target:
            return "COOLING"
        return "HOLDING"

current, target = map(int, input().split())
t = Thermostat(current, target)
print(t.verdict())

class Member:
    def __init__(self, name):
        self.name = name
        self.visits = 0

    def check_in(self):
        self.visits += 1

    def tier(self):
        if self.visits >= 10:
            return "GOLD"
        if self.visits >= 5:
            return "SILVER"
        return "BRONZE"

name = input()
n = int(input())
m = Member(name)
for _ in range(n):
    m.check_in()
print(f"{m.name}: {m.visits} visits {m.tier()}")

class Robot:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def move(self, direction, steps):
        if direction == "U":
            self.y += steps
        elif direction == "D":
            self.y -= steps
        elif direction == "L":
            self.x -= steps
        elif direction == "R":
            self.x += steps

    def report(self):
        return f"{self.x} {self.y}"

x, y = map(int, input().split())
n = int(input())
r = Robot(x, y)
for _ in range(n):
    parts = input().split()
    r.move(parts[0], int(parts[1]))
print(r.report())

class BankAccount:
    def __init__(self, owner, balance):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount

    def withdraw(self, amount):
        if amount > 0 and amount <= self.balance:
            self.balance -= amount
            return True
        return False

owner, balance = input().split()
acc = BankAccount(owner, float(balance))
n = int(input())
for _ in range(n):
    op, amount = input().split()
    amount = float(amount)
    if op == "DEPOSIT":
        acc.deposit(amount)
    elif op == "WITHDRAW":
        if not acc.withdraw(amount):
            print("Insufficient funds")
print(f"Final balance: {acc.balance:.2f}")

class Employee:
    def __init__(self, name, base, rating):
        self.name = name
        self.base = base
        self.rating = rating

    def net_salary(self):
        bonus_rate = 0.20
        if self.rating == "B":
            bonus_rate = 0.10
        elif self.rating == "C":
            bonus_rate = 0.05
        return self.base + self.base * bonus_rate

n = int(input())
for _ in range(n):
    name, base, rating = input().split()
    e = Employee(name, float(base), rating)
    print(f"{e.name}: {e.net_salary():.2f}")

class Cart:
    def __init__(self):
        self.items = []

    def add_item(self, price):
        self.items.append(price)

    def total(self):
        t = 0.0
        for p in self.items:
            t += p
        return t

n = int(input())
cart1 = Cart()
cart2 = Cart()
for _ in range(n):
    which, price = input().split()
    price = float(price)
    if which == "1":
        cart1.add_item(price)
    else:
        cart2.add_item(price)
print(f"Cart1: {cart1.total():.2f}")
print(f"Cart2: {cart2.total():.2f}")

class ClimateUnit:
    def __init__(self, celsius):
        self.__celsius = celsius

    def adjust(self, delta):
        self.__celsius += delta

    def fahrenheit(self):
        return self.__celsius * 9 / 5 + 32

celsius = float(input())
unit = ClimateUnit(celsius)
n = int(input())
for _ in range(n):
    unit.adjust(float(input()))
print(f"Fahrenheit: {unit.fahrenheit():.2f}")
print(f"Internal celsius: {unit._ClimateUnit__celsius:.2f}")

